// Le rapport du matin porte sur les ventes de la veille : on calcule la date
// et le chemin du CSV attendu (produit par le générateur, spec 01), monté dans
// /data à la fois ici et côté service loader.
const dateVeille = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

return [
  {
    json: {
      date_veille: dateVeille,
      csv_path: `/data/export_${dateVeille}.csv`,
    },
  },
];

// Assemblage HTML du rapport (spec 05) : CA en grand, pastilles de tendance
// colorées selon le signe, classements client/produit numérotés, CA par
// région en mini-barres CSS (bonus graphique sans dépendance externe à un
// service de chart en ligne), bandeau d'alerte business si
// kpi_alerte_chute est vrai.
const row = $input.first().json;

const ca = row.ca_veille;
const j7 = row.comparaison_j7;
const mois = row.comparaison_moyenne_mois;
const topClients = row.top_clients || [];
const topProduits = row.top_produits || [];
const region = row.ca_region || [];
const alerte = row.alerte_chute;

const euros = (n) =>
  Number(n).toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';

const dateLongue = (d) => {
  const parsed = new Date(d);
  return Number.isNaN(parsed.getTime())
    ? d
    : parsed.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });
};

const pastille = (ecartValeur, ecartPourcent) => {
  const hausse = ecartValeur >= 0;
  const bg = hausse ? '#f0fdf4' : '#fff1f2';
  const border = hausse ? '#bbf7d0' : '#fecdd3';
  const fg = hausse ? '#15803d' : '#be123c';
  const fleche = hausse ? '▲' : '▼';
  return `<span style="display:inline-block;background:${bg};border:1px solid ${border};color:${fg};font-size:12px;font-weight:700;padding:4px 10px;border-radius:999px;">${fleche} ${ecartPourcent}&nbsp;%</span>`;
};

const ligneComparaison = (label, valeurRef, ecartValeur, ecartPourcent, premiere) => `
  <tr>
    <td style="padding:8px 0;color:#64748b;font-size:13px;${premiere ? '' : 'border-top:1px solid #f1f5f9;'}">${label} <span style="color:#94a3b8;">(${euros(valeurRef)})</span></td>
    <td style="padding:8px 0;text-align:right;${premiere ? '' : 'border-top:1px solid #f1f5f9;'}">${pastille(ecartValeur, ecartPourcent)}</td>
  </tr>`;

const classement = (items, labelKey, couleurRang) =>
  items
    .map((item, index) => {
      const dernier = index === items.length - 1;
      const bordure = dernier ? '' : 'border-bottom:1px solid #f1f5f9;';
      return `
    <tr>
      <td style="width:28px;padding:8px 0;${bordure}"><div style="width:22px;height:22px;border-radius:50%;background:${couleurRang};color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;">${index + 1}</div></td>
      <td style="padding:8px 0;${bordure}color:#1e293b;font-size:13.5px;font-weight:500;">${item[labelKey]}</td>
      <td style="padding:8px 0;${bordure}color:#0f172a;font-size:13.5px;font-weight:600;text-align:right;">${euros(item.ca)}</td>
    </tr>`;
    })
    .join('');

const maxRegionCa = Math.max(...region.map((r) => Number(r.ca)), 1);
const barresRegion = region
  .map((r) => {
    const largeur = Math.max(Math.round((Number(r.ca) / maxRegionCa) * 100), 4);
    return `
    <tr>
      <td style="width:120px;padding:7px 0;color:#475569;font-size:12.5px;">${r.region}</td>
      <td style="padding:7px 8px;">
        <div style="background:#f1f5f9;border-radius:999px;height:8px;overflow:hidden;">
          <div style="background:#8b5cf6;background:linear-gradient(90deg,#6366f1,#8b5cf6);height:8px;border-radius:999px;width:${largeur}%;"></div>
        </div>
      </td>
      <td style="width:84px;padding:7px 0;color:#0f172a;font-size:12.5px;font-weight:600;text-align:right;">${euros(r.ca)}</td>
    </tr>`;
  })
  .join('');

const sectionTitre = (couleur, texte) => `
    <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"><tr>
      <td style="width:3px;"><div style="width:3px;height:14px;background:${couleur};border-radius:2px;"></div></td>
      <td style="padding-left:8px;color:#0f172a;font-size:14px;font-weight:700;">${texte}</td>
    </tr></table>`;

const bandeauAlerte =
  alerte && alerte.alerte
    ? `
  <div style="background:#fff1f2;padding:14px 32px;border-bottom:1px solid #fecdd3;">
    <table role="presentation" cellpadding="0" cellspacing="0"><tr>
      <td style="width:22px;vertical-align:top;">
        <div style="width:20px;height:20px;border-radius:50%;background:#e11d48;color:#fff;font-size:12px;font-weight:700;text-align:center;line-height:20px;">!</div>
      </td>
      <td style="padding-left:10px;">
        <span style="color:#be123c;font-size:13px;font-weight:600;">CA en forte baisse</span>
        <span style="color:#9f1239;font-size:13px;"> — ${alerte.ecart_pourcent}&nbsp;% par rapport à J-7</span>
      </td>
    </tr></table>
  </div>`
    : '';

const html = `
<html>
<body style="margin:0;padding:32px 16px;background:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
<div style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #e2e8f0;">

  <div style="background:#0f172a;background:linear-gradient(135deg,#0f172a,#1e293b);padding:24px 32px;">
    <table role="presentation" cellpadding="0" cellspacing="0"><tr>
      <td style="width:36px;">
        <div style="width:32px;height:32px;border-radius:9px;background:#4f46e5;background:linear-gradient(135deg,#6366f1,#4f46e5);color:#fff;font-size:13px;font-weight:700;text-align:center;line-height:32px;letter-spacing:-0.02em;">RC</div>
      </td>
      <td style="padding-left:12px;">
        <div style="color:#f8fafc;font-size:14px;font-weight:600;letter-spacing:0.01em;">Rapport commercial</div>
        <div style="color:#94a3b8;font-size:12px;margin-top:2px;">Édition du ${dateLongue(ca.date_veille)}</div>
      </td>
    </tr></table>
  </div>

  ${bandeauAlerte}

  <div style="padding:32px 32px 20px 32px;">
    <div style="color:#94a3b8;font-size:11px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;">CA de la veille</div>
    <div style="color:#0f172a;font-size:46px;font-weight:700;letter-spacing:-0.02em;margin-top:6px;font-variant-numeric:tabular-nums;">${euros(ca.ca)}</div>

    <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;margin-top:18px;">
      ${ligneComparaison('vs J-7', j7.ca_j7, j7.ecart_valeur, j7.ecart_pourcent, true)}
      ${ligneComparaison('vs moyenne du mois', mois.ca_moyen_mois, mois.ecart_valeur, mois.ecart_pourcent, false)}
    </table>
  </div>

  <div style="padding:8px 32px 24px 32px;">
    ${sectionTitre('#0f172a', 'Top 5 clients')}
    <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;">${classement(topClients, 'cli_nom', '#0f172a')}</table>
  </div>

  <div style="padding:0 32px 24px 32px;">
    ${sectionTitre('#4f46e5', 'Top 5 produits')}
    <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;">${classement(topProduits, 'art_lib', '#4f46e5')}</table>
  </div>

  <div style="padding:0 32px 8px 32px;">
    ${sectionTitre('#8b5cf6', 'CA par région')}
    <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;">${barresRegion}</table>
  </div>

  <div style="padding:20px 32px 26px 32px;border-top:1px solid #e2e8f0;margin-top:8px;">
    <div style="color:#94a3b8;font-size:11px;text-align:center;line-height:1.6;">
      Généré automatiquement — données fictives, projet de démonstration.<br>Aucun gain de temps réel mesuré.
    </div>
  </div>

</div>
</body>
</html>
`;

return [{ json: { subject: `Rapport commercial — ${ca.date_veille}`, html } }];
